const raw = $json.output?.[0]?.content?.[0]?.text;

if (typeof raw !== 'string' || raw.trim() === '') {
  throw new Error('AI Classifier returned no text output.');
}

const cleaned = raw
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let classification;

try {
  classification = JSON.parse(cleaned);
} catch (error) {
  throw new Error(`Classifier output is not valid JSON: ${error.message}`);
}

const allowedCategories = [
  'work',
  'personal',
  'finance',
  'appointment',
  'security',
  'newsletter',
  'promotion',
  'other',
];

if (typeof classification.important !== 'boolean') {
  throw new Error('"important" must be true or false.');
}

if (
  typeof classification.category !== 'string' ||
  !allowedCategories.includes(classification.category)
) {
  throw new Error(
    `"category" must be one of: ${allowedCategories.join(', ')}`
  );
}

if (
  typeof classification.reason !== 'string' ||
  classification.reason.trim() === ''
) {
  throw new Error('"reason" must be a non-empty string.');
}

return {
  json: {
    valid: true,
    important: classification.important,
    category: classification.category,
    reason: classification.reason.trim(),
  },
};

