const raw =
  $json.content ??
  $json.text ??
  $json.response ??
  $json.output?.[0]?.content?.[0]?.text;

// 2. Prüfen, ob überhaupt Text angekommen ist
if (typeof raw !== 'string' || raw.trim() === '') {
  throw new Error('Summarizer returned no text output.');
}

// 3. Falls Claude ```json ... ``` benutzt hat, entfernen wir diese Markdown-Hülle
const cleaned = raw
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

// 4. JSON-Text in ein echtes JavaScript-Objekt umwandeln
let summary;

try {
  summary = JSON.parse(cleaned);
} catch (error) {
  throw new Error(`Summarizer output is not valid JSON: ${error.message}`);
}

// 5. Erlaubte Prioritäten festlegen
const allowedPriorities = ['low', 'medium', 'high'];

// 6. summary validieren
if (
  typeof summary.summary !== 'string' ||
  summary.summary.trim() === ''
) {
  throw new Error('"summary" must be a non-empty string.');
}

// 7. action_items validieren
if (!Array.isArray(summary.action_items)) {
  throw new Error('"action_items" must be an array.');
}

for (const item of summary.action_items) {
  if (typeof item !== 'string' || item.trim() === '') {
    throw new Error(
      'Every item inside "action_items" must be a non-empty string.'
    );
  }
}

// 8. deadline validieren
if (
  summary.deadline !== null &&
  typeof summary.deadline !== 'string'
) {
  throw new Error('"deadline" must be a string or null.');
}

// 9. priority validieren
if (
  typeof summary.priority !== 'string' ||
  !allowedPriorities.includes(summary.priority)
) {
  throw new Error(
    '"priority" must be exactly one of: low, medium, high.'
  );
}

// 10. Sauberen, normalisierten Output an die nächste Node weitergeben
return {
  json: {
    valid: true,
    summary: summary.summary.trim(),
    action_items: summary.action_items.map(item => item.trim()),
    deadline:
      typeof summary.deadline === 'string'
        ? summary.deadline.trim()
        : null,
    priority: summary.priority
  }
};

